package com.ruoyi.metal.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import com.ruoyi.common.core.redis.RedisCache;import com.ruoyi.metal.security.FactoryScope;import org.springframework.transaction.support.TransactionSynchronizationManager;
class SessionInvalidationTest{
 @Test void databaseVersionStillChangesWhenRedisFails(){var j=mock(JdbcTemplate.class);var c=mock(RedisCache.class);when(c.keys(anyString())).thenThrow(new IllegalStateException("Redis fixture"));assertDoesNotThrow(()->new FactoryScope(j,c).invalidate(Set.of(10L)));verify(j).update(contains("auth_version=auth_version+1"),eq(10L));}
 @Test void cacheCleanupOnlyRunsAfterCommit(){var j=mock(JdbcTemplate.class);var c=mock(RedisCache.class);when(c.keys(anyString())).thenReturn(List.of());TransactionSynchronizationManager.initSynchronization();try{new FactoryScope(j,c).invalidate(Set.of(10L));verify(c,never()).keys(anyString());for(var sync:TransactionSynchronizationManager.getSynchronizations())sync.afterCommit();verify(c).keys("login_tokens:*");}finally{TransactionSynchronizationManager.clearSynchronization();}}
 @Test void rollbackDoesNotCleanupCache(){var j=mock(JdbcTemplate.class);var c=mock(RedisCache.class);TransactionSynchronizationManager.initSynchronization();try{new FactoryScope(j,c).invalidate(Set.of(10L));for(var sync:TransactionSynchronizationManager.getSynchronizations())sync.afterCompletion(1);verifyNoInteractions(c);}finally{TransactionSynchronizationManager.clearSynchronization();}}
}
